  'DHL':       { falsa:[96,56,55,94,114,82,50,73], cruzada:[0,1,0,3,0,1,1,2], mensajeria:[37,8,11,6,9,10,7,9], cambio:[0,0,0,5,11,3,2,0], internos:[2,3,2,0,0,0,0,0] },
